import{Lt as e,Vt as t,Z as n,_t as r,bt as i,vt as a}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";var o=JSON.parse(`{"title":"如何解决 Zotero 中 pdf 文件图片上有黑色遮挡的问题","description":"","frontmatter":{"title":"如何解决 Zotero 中 pdf 文件图片上有黑色遮挡的问题","date":"2023-09-14T21:17:47.000Z","updated":"2023-09-14T16:51:54.000Z","redirectFrom":"/user-guide/faqs/%E8%A7%A3%E5%86%B3pdf%E5%9B%BE%E7%89%87%E4%B8%8A%E7%9A%84%E9%BB%91%E8%89%B2%E9%81%AE%E6%8C%A1.html"},"headers":[],"relativePath":"user-guide/faqs/pdf-black-mask.md","filePath":"wiki/user-guide/faqs/pdf-black-mask.md"}`),s={name:`user-guide/faqs/pdf-black-mask.md`};function c(n,o,s,c,l,u){let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[o[0]||=a(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /user-guidefaqspdf-black-mask.md for this page in Markdown format</div><h1 id="如何解决-zotero-中-pdf-文件图片上有黑色遮挡的问题" tabindex="-1">如何解决 Zotero 中 pdf 文件图片上有黑色遮挡的问题 <a class="header-anchor" href="#如何解决-zotero-中-pdf-文件图片上有黑色遮挡的问题" aria-label="Permalink to “如何解决 Zotero 中 pdf 文件图片上有黑色遮挡的问题”">​</a></h1><p>部分同学在使用 Zotero 官方阅读器阅读 pdf 的时候，可能会碰到图片出现黑色遮挡的情况。</p><p><img src="/assets/zotero-%E9%BB%91%E8%89%B2%E9%81%AE%E6%8C%A1.BHW1udkU.png" alt="黑色遮挡" width="787" height="693"></p><p>根据 <a href="https://forums.zotero.org/discussion/97306/black-shade-on-the-figures-when-opening-pdf-by-zotero-report-id-942401037" target="_blank" rel="noreferrer">Zotero 官方答复</a> ，这个问题可能是由显卡不兼容导致，可以尝试通过更新显卡驱动来解决，或者通过修改 Zotero 设置，以降低部分图形性能为代价，解决这个问题。</p><p>具体操作步骤如下：</p><ol><li>在菜单编辑选择「设置」： <img src="/assets/zotero-%E7%BC%96%E8%BE%91%E5%99%A8.DSl04uzc.png" alt="编辑器" width="616" height="556"></li><li>弹出如下图所示的对话框。 点击「I accept the risk」 <img src="/assets/zotero-%E6%88%91%E5%90%8C%E6%84%8F%E6%89%BF%E6%8B%85%E9%A3%8E%E9%99%A9.5QGn1TLl.png" alt="同意承担风险" width="1479" height="1030"></li><li>在搜索框中输入 acceleration，双击搜索到的 layers.acceleration.disabled，Value 将变为 true。然后重新启动 Zotero，即可解决问题。 <img src="/assets/zotero-layers.acceleration.disabled.BRMAckgp.png" alt="将 layers.acceleration.disabled 设置为 true" width="1495" height="1069"></li></ol>`,7),i(d),i(f)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};